import{_ as t,l,o as e,c as n,v as r,p as s,x as o,d as h,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"球差","description":"","frontmatter":{"title":"球差","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/spherical-aberration.md","filePath":"litho/spherical-aberration.md","lastUpdated":1789023840000}'),d={name:"litho/spherical-aberration.md"};function c(B,a,_,A,m,f){const i=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="球差" tabindex="-1">球差 <a class="header-anchor" href="#球差" aria-label="Permalink to &quot;球差&quot;">​</a></h1><div class="epigraph"><p>Zernike 表已经把光瞳相位展开；初级球差是其中旋转对称的 $\\rho^4$ 项——边缘带的焦点相对近轴移动，糊斑仍圆，只是最佳焦面随孔径环走。</p><footer>—— Born &amp; Wolf, Principles of Optics 对初级（Seidel）球差的讨论</footer></div><p><a href="/litho/zernike-aberrations">上一课</a>把 \\(W\\) 收成系数向量，并声明 Fringe / Noll 不可混号。缺口是：<strong>先把初级球差这一项讲完</strong>，而不是停留在「表上有这一列」。彗差的不对称留给<a href="/litho/coma-aberration">下一课</a>。不要从瑞利 CD 重讲，也不要引用未公开的镜头球差预算。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>展开式里球差与离焦都旋转对称，容易被当成同一种糊。离焦是 \\(\\rho^2\\)（Fringe \\(Z_4\\)），初级球差是 \\(\\rho^4\\)（Fringe 常记在 \\(Z_9\\) 一带，含配平用的低阶项）。边缘光线的光程比近轴多出随 \\(\\rho^4\\) 涨的一块，不同孔径环的焦点沿轴错开。缺口因此是这根<strong>带焦点移动</strong>，而不是再解释正交多项式。</p><p>轴上点物的几何像差里，球差是唯一不随视场变的初级项（Seidel \\(S_I\\)）。视场一离轴，彗差、像散会来；本课先钉轴上。</p><h3 id="配平不是把球差消掉" tabindex="-1">配平不是把球差消掉 <a class="header-anchor" href="#配平不是把球差消掉" aria-label="Permalink to &quot;配平不是把球差消掉&quot;">​</a></h3><p>加 \\(Z_4\\) 可以把某一个环带的焦点拉回晶圆，RMS 下降，边缘与近轴仍对不齐。计量上的「球差已补偿」往往指配平后的残差小，不是 \\(\\rho^4\\) 系数为零。通过焦点的 CD 不对称、等焦点漂移，常常是配平选择的后果。</p><p><span class="marginnote">报球差必须带约定：Noll 与 Fringe 的「第几项」不是同一个多项式。上一课已经警告过；球差是最常报错号的一列。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Seidel 初级球差波前 \\(W\\propto \\rho^4\\)（再按孔径与视场的无量纲化写成 \\(S_I\\)）。成像核仍圆对称：点扩散是圆斑，没有彗尾，没有 H/V 劈裂。密图形走光瞳边缘，对 \\(\\rho^4\\) 最敏感；孤立线频谱更宽，吃到的是配平后的折中。TCC 对每个场点可以乘不同的球差系数——轴上理想不代表狭缝边缘理想。</p><p>Born &amp; Wolf 把球差与正弦条件、齐明条件放在一起：设计上用多个折射面抵消 \\(S_I\\)，残差进 Zernike。本课不追透镜配方，只要求空中像仿真把这一项乘进 \\(P\\)。</p><h3 id="通过焦点的各向同性" tabindex="-1">通过焦点的各向同性 <a class="header-anchor" href="#通过焦点的各向同性" aria-label="Permalink to &quot;通过焦点的各向同性&quot;">​</a></h3><p>Bossung 在球差下仍近似上下对称的「H/V 同类」，但最佳焦随节距走：不同空间频率对应不同有效环带。这与照明 \\(\\sigma\\) 改变环带权重是同一逻辑。不要把它写成像散——像散会把水平和垂直的最佳焦劈开。</p><p><span class="marginnote">热致球差随曝光负荷变。冷态出厂的 \\(c_9\\) 不等于扫描时的 \\(c_9\\)。控制上这是镜头加热补偿，与定义无关。</span></p>',15)),(e(),s(E,null,{default:o(()=>[p(i,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22Zernike%20%E5%B1%95%E5%BC%80%22%5D%20--%3E%20SA%5B%22%E5%88%9D%E7%BA%A7%E7%90%83%E5%B7%AE%20%CF%81%E2%81%B4%22%5D%0A%20%20SA%20--%3E%20ZONE%5B%22%E7%8E%AF%E5%B8%A6%E7%84%A6%E7%82%B9%E6%B2%BF%E8%BD%B4%E9%94%99%E5%BC%80%22%5D%0A%20%20Z4%5B%22%E7%A6%BB%E7%84%A6%20Z4%22%5D%20--%3E%20BAL%5B%22%E9%85%8D%E5%B9%B3%E6%9F%90%E4%B8%80%E7%8E%AF%22%5D%0A%20%20SA%20--%3E%20BAL%0A%20%20ZONE%20--%3E%20CD%5B%22%E5%90%84%E5%90%91%E5%90%8C%E6%80%A7%E7%B3%8A%20%2F%20%E8%8A%82%E8%B7%9D%E4%BE%9D%E8%B5%96%E7%84%A6%E6%BC%82%22%5D%0A%20%20CD%20--%3E%20NEXT%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%BD%97%E5%B7%AE%E4%B8%8D%E5%AF%B9%E7%A7%B0%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>相位 \\(\\rho^4\\) 在像面与一个圆对称但带球差的核卷积。边缘带相对近轴有额外光程，相干叠加在最佳配平面上仍有残差环。频率上，越靠近截止，权重越靠光瞳边，\\(\\rho^4\\) 越大，NILS 先掉——与离焦「高频先死」同构，径向幂次更高，配平曲线不同。</p><p>同一套系数乘在 Jones 两通道上。球差不是偏振；TM 已弱的密线对残差更脆。</p><h3 id="后课默认的接口" tabindex="-1">后课默认的接口 <a class="header-anchor" href="#后课默认的接口" aria-label="Permalink to &quot;后课默认的接口&quot;">​</a></h3><p>说到轴上、旋转对称的残差，先问初级（及高阶）球差与所用配平，再问焦深窗口。彗差、像散、畸变不要塞进这一项。色差会让 \\(S_I\\) 随 \\(\\lambda\\) 变，本课单色。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>球差展开不含杂散光、不含多层膜散射。EUV 反射镜同样用 \\(\\rho^4\\) 说话，High-NA 变形光瞳要另写径向坐标。禁止编造未公开的 RMS 毫波数；Born &amp; Wolf 的 Seidel 项与上一课的拟合接口已经够用。截断阶数之外的高阶球差照样吃对比。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>初级球差是旋转对称的 \\(\\rho^4\\)；离焦是 \\(\\rho^2\\)，可配平不可等同。</li><li>糊斑仍圆；最佳焦随孔径环 / 节距走。</li><li>报系数必须声明 Fringe 或 Noll。</li><li>与 TE/TM 相乘，不替代矢量损失。</li><li>不对称的彗差下一课。</li><li>出处：Born &amp; Wolf, <em>Principles of Optics</em>。</li></ul>',9))])}const S=t(d,[["render",c]]);export{b as __pageData,S as default};
